    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        handleMetricChatMessage(event);
        handleClanChatRelayOutgoing(event);
    }

    private void handleStatChanged(StatChanged event)
    {
        if (!config.enableBingoMetricTracking() || client.getGameState() != GameState.LOGGED_IN || event == null)
        {
            return;
        }

        final String skillMetricKey = metricKeyForSkill(event.getSkill());
        if (skillMetricKey.isEmpty())
        {
            return;
        }

        final int currentXp = Math.max(0, event.getXp());
        final Integer previousXp = lastSkillXpByMetricKey.put(skillMetricKey, currentXp);
        if (previousXp == null || currentXp <= previousXp)
        {
            return;
        }

        final long gained = currentXp - previousXp;
        // XP changes are frequent. Queue the cumulative checkpoint so the next
        // unified poll can submit one idempotent update per metric tile.
        queueXpMetricDelta(skillMetricKey, gained, event.getSkill().getName() + " XP");
        queueXpMetricDelta("computed:overall_xp", gained, "Overall XP");
    }

    private void handleMetricChatMessage(ChatMessage event)
    {
        if (!config.enableBingoMetricTracking() || client.getGameState() != GameState.LOGGED_IN || event == null)
        {
            return;
        }
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }

        final String message = cleanText(event.getMessage());
        final String normalized = normalizeName(message);
        if (normalized.startsWith("your ") && normalized.contains(" kill count is:"))
        {
            final int nameStart = "your ".length();
            final int nameEnd = normalized.indexOf(" kill count is:");
            final String bossName = normalized.substring(nameStart, nameEnd).trim();
            final int count = parseTrailingCount(normalized.substring(nameEnd + " kill count is:".length()));
            if (!bossName.isEmpty() && count > 0)
            {
                applyAbsoluteMetricCount("boss:" + metricKeySlug(bossName), count, bossName + " KC");
            }
            return;
        }

        if (normalized.startsWith("you have completed ") && normalized.contains(" treasure trail"))
        {
            final int count = parseFirstCount(normalized.substring("you have completed ".length()));
            final String tier = clueTierFromMessage(normalized);
            if (count > 0 && !tier.isEmpty())
            {
                applyAbsoluteMetricCount("activity:clue_scrolls_" + tier, count, tier + " clues");
            }
        }
    }

    private void handleClanChatRelayOutgoing(ChatMessage event)
    {
        if (event == null || clanChatRelayExecutor == null)
        {
            return;
        }

        String senderName = cleanText(event.getName());
        if (senderName.isEmpty())
        {
            senderName = cleanText(event.getSender());
        }
        final String message = cleanText(event.getMessage());
        final boolean memberMessage = (event.getType() == ChatMessageType.CLAN_CHAT || event.getType() == ChatMessageType.CLAN_GUEST_CHAT)
            && isConfiguredClanChatChannel(event.getType());
        final boolean achievementBroadcast = event.getType() == ChatMessageType.CLAN_MESSAGE
            && isConfiguredClanChatChannel(ChatMessageType.CLAN_CHAT)
            && !isClanChatInstruction(message)
            && !isGroupIronmanAnnouncement(message);
        if ((!memberMessage && !achievementBroadcast) || message.isEmpty() || isRecentInjectedDiscordMessage(senderName, message) || (memberMessage && senderName.isEmpty()))
        {
            return;
        }

        final String endpoint = resolveClanChatRelayEndpoint();
        if (endpoint.isEmpty() || !clanChatRelayOutgoingActive)
        {
            return;
        }

        final String relayRsn = currentLocalPlayerName();
        final String resolvedSenderName = senderName;
        clanChatRelayExecutor.execute(() -> submitClanChatRelayMessage(endpoint, achievementBroadcast ? "Clan Achievement" : resolvedSenderName, message, achievementBroadcast, relayRsn));
    }

    private static boolean isClanChatInstruction(String message)
    {
        final String normalized = normalizeName(message);
        return normalized.startsWith("to talk in your clan's channel");
    }

    private static boolean isGroupIronmanAnnouncement(String message)
    {
        final String normalized = normalizeName(message);
        return normalized.contains("group ironman") || normalized.contains("groupim");
    }

    private boolean isConfiguredClanChatChannel(ChatMessageType type)
    {
        final String expectedName = clanChatRelayClanName;
        if (expectedName.isEmpty())
        {
            return false;
        }

        final ClanChannel channel = type == ChatMessageType.CLAN_GUEST_CHAT
            ? client.getGuestClanChannel()
            : client.getClanChannel();
        return channel != null && expectedName.equals(normalizeName(channel.getName()));
    }

    private void submitClanChatRelayMessage(String endpoint, String senderName, String message, boolean system, String relayRsn)
    {
        final JsonObject payload = new JsonObject();
        payload.addProperty("source", "plugin");
        payload.addProperty("senderName", senderName);
        payload.addProperty("message", message);
        payload.addProperty("system", system);
        payload.addProperty("relayRsn", relayRsn);
        final Request request = new Request.Builder()
            .url(endpoint)
            .header("Accept", "application/json")
            .post(RequestBody.create(JSON, gson.toJson(payload)))
            .build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() && config.debug())
            {
                log.debug("Clan chat relay returned HTTP {}", response.code());
            }
        }
        catch (IOException ex)
        {
            if (config.debug())
            {
                log.debug("Clan chat relay submission failed", ex);
            }
        }
    }

    private void applyAbsoluteMetricCount(String metricKey, int absoluteCount, String sourceLabel)
    {
        final String cleanedMetricKey = cleanText(metricKey);
        if (cleanedMetricKey.isEmpty() || absoluteCount <= 0)
        {
            return;
        }

        final Integer previousCount = lastAbsoluteMetricCountByKey.put(cleanedMetricKey, absoluteCount);
        final long gained = previousCount == null || absoluteCount <= previousCount ? 1L : absoluteCount - previousCount;
        applyMetricDelta(cleanedMetricKey, gained, sourceLabel);
    }

    private void applyMetricDelta(String metricKey, long gained, String sourceLabel)
    {
        if (gained <= 0L)
        {
            return;
        }

        final String playerRsn = currentLocalPlayerName();
        final String endpoint = resolveBingoMetricEndpoint();
        if (playerRsn.isEmpty() || endpoint.isEmpty())
        {
            return;
        }

        final List<BingoBoardCell> matchingTiles = activeMetricTiles(metricKey);
        if (matchingTiles.isEmpty())
        {
            return;
        }

        for (BingoBoardCell cell : matchingTiles)
        {
            final String tileId = cleanText(cell.getTileId());
            if (tileId.isEmpty() || cell.isCompleted() || cell.getTargetValue() <= 0L)
            {
                continue;
            }

            final long localGain = metricLocalGains.merge(tileId, gained, Long::sum);
            final long pluginProgress = cell.getRequiredCompletions() > 1
                ? localGain
                : Math.max(0L, cell.getProgressValue()) + localGain;
            submitMetricClaim(endpoint, playerRsn, cell, pluginProgress, gained, sourceLabel);
            maybeRemindWomUpdateRequired(cell, pluginProgress);
        }
    }

    private synchronized void queueXpMetricDelta(String metricKey, long gained, String sourceLabel)
    {
        if (gained <= 0L)
        {
            return;
        }

        final String playerRsn = currentLocalPlayerName();
        if (playerRsn.isEmpty())
        {
            return;
        }

        final List<BingoBoardCell> matchingTiles = activeMetricTiles(metricKey);
        if (matchingTiles.isEmpty())
        {
            return;
        }

        final long now = System.currentTimeMillis();
        for (BingoBoardCell cell : matchingTiles)
        {
            final String tileId = cleanText(cell.getTileId());
            final String cleanedMetricKey = cleanText(cell.getMetricKey());
            if (tileId.isEmpty() || cleanedMetricKey.isEmpty() || cell.isCompleted() || cell.getTargetValue() <= 0L)
            {
                continue;
            }

            final long localGain = metricLocalGains.merge(tileId, gained, Long::sum);
            final long pluginProgress = cell.getRequiredCompletions() > 1
                ? localGain
                : Math.max(0L, cell.getProgressValue()) + localGain;
            final String metricBatchKey = xpMetricBatchKey(playerRsn, tileId, cleanedMetricKey, cell.getTargetValue());
            final String existingEventId = pendingXpBatchByMetric.get(metricBatchKey);
            final PendingXpMetricBatch existing = existingEventId == null ? null : pendingXpMetricBatches.get(existingEventId);

            if (existing != null && !existing.inFlight)
            {
                existing.gainedValue = localGain;
                existing.pluginProgressValue = pluginProgress;
                existing.metricLabel = firstNonBlank(cell.getMetricLabel(), cell.getLabel(), sourceLabel);
            }
            else
            {
                final PendingXpMetricBatch batch = new PendingXpMetricBatch();
                batch.eventId = UUID.randomUUID().toString();
                batch.metricBatchKey = metricBatchKey;
                batch.playerRsn = playerRsn;
                batch.tileId = tileId;
                batch.metricKey = cleanedMetricKey;
                batch.metricLabel = firstNonBlank(cell.getMetricLabel(), cell.getLabel(), sourceLabel);
                batch.gainedValue = localGain;
                batch.pluginProgressValue = pluginProgress;
                batch.targetValue = cell.getTargetValue();
                batch.capturedAtUtc = CAPTURED_AT_FORMAT.format(Instant.now().truncatedTo(ChronoUnit.SECONDS));
                batch.createdAtMillis = now;
                batch.dueAtMillis = now + XP_METRIC_BATCH_MILLIS;
                pendingXpMetricBatches.put(batch.eventId, batch);
                pendingXpBatchByMetric.put(metricBatchKey, batch.eventId);
            }
            maybeRemindWomUpdateRequired(cell, pluginProgress);
        }
        persistPendingXpMetricBatches();
    }

    private synchronized JsonArray dueXpMetricBatches(String playerRsn, long now)
    {
        final JsonArray batches = new JsonArray();
        final List<PendingXpMetricBatch> pending = new ArrayList<>(pendingXpMetricBatches.values());
        pending.sort((left, right) -> Long.compare(left.createdAtMillis, right.createdAtMillis));
        for (PendingXpMetricBatch batch : pending)
        {
            if (batches.size() >= 50 || batch == null || batch.dueAtMillis > now || !sameNormalizedName(batch.playerRsn, playerRsn))
            {
                continue;
            }

            batch.inFlight = true;
            final JsonObject payload = new JsonObject();
            payload.addProperty("eventId", batch.eventId);
            payload.addProperty("tileId", batch.tileId);
            payload.addProperty("metricKey", batch.metricKey);
            payload.addProperty("metricLabel", batch.metricLabel);
            payload.addProperty("gainedValue", batch.gainedValue);
            payload.addProperty("pluginProgressValue", batch.pluginProgressValue);
            payload.addProperty("targetValue", batch.targetValue);
            payload.addProperty("capturedAtUtc", batch.capturedAtUtc);
            batches.add(payload);
        }
        if (batches.size() > 0)
        {
            persistPendingXpMetricBatches();
        }
        return batches;
    }

    private synchronized void applyXpMetricBatchResults(JsonArray results)
    {
        boolean changed = false;
        for (JsonElement element : results)
        {
            if (!element.isJsonObject())
            {
                continue;
            }

            final JsonObject result = element.getAsJsonObject();
            final String eventId = cleanText(jsonString(result, "eventId"));
            final PendingXpMetricBatch batch = eventId.isEmpty() ? null : pendingXpMetricBatches.get(eventId);
            if (batch == null)
            {
                continue;
            }

            if (jsonBoolean(result, "accepted") || !jsonBoolean(result, "retry"))
            {
                pendingXpMetricBatches.remove(eventId);
                pendingXpBatchByMetric.remove(batch.metricBatchKey, eventId);
            }
            else
            {
                batch.inFlight = false;
            }
            changed = true;
        }
        if (changed)
        {
            persistPendingXpMetricBatches();
        }
    }

    private synchronized void loadPendingXpMetricBatches()
    {
        if (configManager == null)
        {
            return;
        }

        final String stored = configManager.getConfiguration("parentsguild", XP_BATCHES_CONFIG_KEY);
        if (stored == null || stored.trim().isEmpty())
        {
            return;
        }

        try
        {
            final JsonElement parsed = gson.fromJson(stored, JsonElement.class);
            if (parsed == null || !parsed.isJsonArray())
            {
                return;
            }

            for (JsonElement element : parsed.getAsJsonArray())
            {
                if (!element.isJsonObject())
                {
                    continue;
                }

                final PendingXpMetricBatch batch = gson.fromJson(element, PendingXpMetricBatch.class);
                if (!isValidPendingXpMetricBatch(batch))
                {
                    continue;
                }

                batch.inFlight = false;
                pendingXpMetricBatches.put(batch.eventId, batch);
                final String currentEventId = pendingXpBatchByMetric.get(batch.metricBatchKey);
                final PendingXpMetricBatch current = currentEventId == null ? null : pendingXpMetricBatches.get(currentEventId);
                if (current == null || batch.createdAtMillis >= current.createdAtMillis)
                {
                    pendingXpBatchByMetric.put(batch.metricBatchKey, batch.eventId);
                }
            }
        }
        catch (RuntimeException ex)
        {
            log.warn("Discarding unreadable pending ParentsGuild XP metric batches", ex);
            pendingXpMetricBatches.clear();
            pendingXpBatchByMetric.clear();
        }
    }

    private synchronized void restorePendingXpLocalGainsForPlayer(String playerRsn)
    {
        metricLocalGains.clear();
        final String normalizedPlayerRsn = normalizeName(playerRsn);
        if (normalizedPlayerRsn.isEmpty())
        {
            return;
        }
        for (PendingXpMetricBatch batch : pendingXpMetricBatches.values())
        {
            if (batch != null && normalizedPlayerRsn.equals(normalizeName(batch.playerRsn)))
            {
                metricLocalGains.merge(batch.tileId, batch.gainedValue, (existing, value) -> Math.max(existing, value));
            }
        }
    }

    private synchronized void persistPendingXpMetricBatches()
    {
        if (configManager == null || writingPendingXpMetricBatches)
        {
            return;
        }

        writingPendingXpMetricBatches = true;
        try
        {
            configManager.setConfiguration("parentsguild", XP_BATCHES_CONFIG_KEY, gson.toJson(new ArrayList<>(pendingXpMetricBatches.values())));
        }
        finally
        {
            writingPendingXpMetricBatches = false;
        }
    }

    private static boolean isValidPendingXpMetricBatch(PendingXpMetricBatch batch)
    {
        return batch != null
            && cleanText(batch.eventId).matches("[A-Za-z0-9-]{8,64}")
            && !cleanText(batch.metricBatchKey).isEmpty()
            && !cleanText(batch.playerRsn).isEmpty()
            && !cleanText(batch.tileId).isEmpty()
            && !cleanText(batch.metricKey).isEmpty()
            && batch.gainedValue > 0L
            && batch.targetValue > 0L
            && !cleanText(batch.capturedAtUtc).isEmpty();
    }

    private static String xpMetricBatchKey(String playerRsn, String tileId, String metricKey, long targetValue)
    {
        return normalizeName(playerRsn) + "|" + cleanText(tileId) + "|" + cleanText(metricKey) + "|" + targetValue;
    }

    private void maybeRemindWomUpdateRequired(BingoBoardCell cell, long pluginProgress)
    {
        if (cell == null || pluginProgress < cell.getTargetValue())
        {
            return;
        }

        final String tileId = cleanText(cell.getTileId());
        if (tileId.isEmpty() || !metricWomUpdateReminderTileIds.add(tileId))
        {
            return;
        }

        sendGameMessage("ParentsGuild: \"" + cell.getLabel() + "\" appears complete locally. Log out and back in so Wise Old Man can update and confirm it.");
    }

    private List<BingoBoardCell> activeMetricTiles(String metricKey)
    {
        final List<BingoBoardCell> tiles = new ArrayList<>();
        final String cleanedMetricKey = cleanText(metricKey);
        if (cleanedMetricKey.isEmpty() || !bingoBoardState.isVisible())
        {
            return tiles;
        }

        for (List<BingoBoardCell> row : bingoBoardState.getGrid())
        {
            for (BingoBoardCell cell : row)
            {
                if (cell != null
                    && "metric".equals(normalizeName(cell.getTileType()))
                    && cleanedMetricKey.equals(cleanText(cell.getMetricKey()))
                    && !cell.isCompleted())
                {
                    tiles.add(cell);
                }
            }
        }
        return tiles;
    }

    private void submitMetricClaim(String endpoint, String playerRsn, BingoBoardCell cell, long pluginProgress, long localGain, String sourceLabel)
    {
        final String achievedAtUtc = CAPTURED_AT_FORMAT.format(Instant.now().truncatedTo(ChronoUnit.SECONDS));
        final String eventId = buildMetricEventId(playerRsn, cell.getTileId(), cell.getMetricKey(), cell.getTargetValue(), achievedAtUtc);
        final JsonObject payload = new JsonObject();
        payload.addProperty("source", "runelite_plugin");
        payload.addProperty("eventId", eventId);
        payload.addProperty("playerRsn", playerRsn);
        payload.addProperty("tileId", cell.getTileId());
        payload.addProperty("metricKey", cell.getMetricKey());
        payload.addProperty("metricLabel", firstNonBlank(cell.getMetricLabel(), cell.getLabel(), sourceLabel));
        payload.addProperty("gainedValue", localGain);
        payload.addProperty("pluginProgressValue", pluginProgress);
        payload.addProperty("targetValue", cell.getTargetValue());
        payload.addProperty("achievedAtUtc", achievedAtUtc);

        final Request request = new Request.Builder()
            .url(endpoint)
            .header("Accept", "application/json")
            .post(RequestBody.create(JSON, gson.toJson(payload)))
            .build();

        okHttpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.warn("Bingo metric submission failed", e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response httpResponse = response)
                {
                    final String responseBody = httpResponse.body() != null ? httpResponse.body().string() : "";
                    if (!httpResponse.isSuccessful())
                    {
                        log.warn("Bingo metric endpoint returned HTTP {}: {}", httpResponse.code(), responseBody);
                        return;
                    }

                    final JsonObject responseJson = parseResponseJson(responseBody);
                    final String outcome = jsonString(responseJson, "outcome");
                    if ("approved".equals(outcome))
                    {
                        sendGameMessage("ParentsGuild: WOM confirmed \"" + firstNonBlank(jsonString(responseJson, "tileLabel"), cell.getLabel()) + "\".");
                        requestBingoStatusRefresh(true);
                        requestBingoBoardRefresh(true);
                        return;
                    }
                    if ("submitted".equals(outcome))
                    {
                        requestBingoStatusRefresh(true);
                        requestBingoBoardRefresh(true);
                        return;
                    }
                    debugLog("Quiet bingo metric outcome={} tile={} response={}", outcome, cell.getLabel(), responseBody);
                }
            }
        });
    }

