    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (RECOVERY_INTERFACE_IDS.contains(event.getGroupId()))
        {
            recoveryInterfaceOpen = false;
        }
        if (STORAGE_INTERFACE_IDS.contains(event.getGroupId()))
        {
            storageInterfaceOpen = false;
        }
    }

    @Subscribe
