    // Drop detection

    private void handleRewardContainer(int containerId, ItemContainer itemContainer)
    {
        final Map<Integer, Integer> currentItems = aggregateContainerItems(itemContainer);
        final Map<Integer, Integer> previousItems = rewardContainerSnapshots.get(containerId);
        if (currentItems.isEmpty())
        {
            rewardContainerSnapshots.remove(containerId);
            return;
        }

        rewardContainerSnapshots.put(containerId, currentItems);

        final List<ItemStack> gainedItems = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : currentItems.entrySet())
        {
            final int itemId = entry.getKey();
            final int quantity = entry.getValue();
            final int previousQuantity = previousItems == null ? 0 : previousItems.getOrDefault(itemId, 0);
            final int gainedQuantity = quantity - previousQuantity;
            if (gainedQuantity > 0)
            {
                gainedItems.add(new ItemStack(itemId, gainedQuantity));
            }
        }

        if (!gainedItems.isEmpty())
        {
            handleLoot(rewardContainerSourceName(containerId), gainedItems);
        }
    }

    private void handleNpcInventoryReward(ItemContainer itemContainer)
    {
        final Map<Integer, Integer> currentItems = aggregateContainerItems(itemContainer);
        if (!inventorySnapshotInitialized)
        {
            inventorySnapshot.putAll(currentItems);
            inventorySnapshotInitialized = true;
            return;
        }

        final NpcInventoryRewardInteraction interaction = pendingNpcInventoryRewardInteraction;
        final boolean npcRewardWindowActive = interaction != null && interaction.getExpiresAtMillis() >= System.currentTimeMillis();
        if (interaction != null && !npcRewardWindowActive)
        {
            pendingNpcInventoryRewardInteraction = null;
        }
        final StorageWithdrawalInteraction storageWithdrawal = pendingStorageWithdrawalInteraction;
        if (storageWithdrawal != null && storageWithdrawal.getExpiresAtMillis() < System.currentTimeMillis())
        {
            pendingStorageWithdrawalInteraction = null;
        }

        final boolean recoveryActive = isRecoveryActive();
        if (recoveryActive)
        {
            debugLog("Skipping inventory gains from death recovery: {}", recoverySourceName());
            pendingRecoveryInteraction = null;
            inventorySnapshot.clear();
            inventorySnapshot.putAll(currentItems);
            return;
        }

        if (storageInterfaceOpen && !npcRewardWindowActive)
        {
            debugLog("Skipping inventory gains from storage withdrawal");
            inventorySnapshot.clear();
            inventorySnapshot.putAll(currentItems);
            return;
        }
        if (clueStashInteractionExpiresAtMillis >= System.currentTimeMillis())
        {
            debugLog("Skipping inventory gains from stash interaction");
            inventorySnapshot.clear();
            inventorySnapshot.putAll(currentItems);
            return;
        }
        clueStashInteractionExpiresAtMillis = 0L;

        final List<ItemStack> gainedItems = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : currentItems.entrySet())
        {
            final int gainedQuantity = entry.getValue() - inventorySnapshot.getOrDefault(entry.getKey(), 0);
            if (gainedQuantity > 0 && (npcRewardWindowActive || (isUntradeableItem(entry.getKey()) && !isPendingStorageWithdrawal(entry.getKey()))))
            {
                gainedItems.add(new ItemStack(entry.getKey(), gainedQuantity));
            }
        }
        if (!gainedItems.isEmpty())
        {
            handleLoot(
                npcRewardWindowActive ? "NPC reward: " + interaction.getNpcName() : "Untradable inventory reward",
                gainedItems
            );
        }

        inventorySnapshot.clear();
        inventorySnapshot.putAll(currentItems);
    }

    private boolean isUntradeableItem(int itemId)
    {
        try
        {
            final ItemComposition item = itemManager.getItemComposition(canonicalItemId(itemId));
            return item != null && !item.isTradeable();
        }
        catch (RuntimeException ex)
        {
            debugLog("Could not determine whether item {} is tradable: {}", itemId, ex.getMessage());
            return false;
        }
    }

    private boolean isPendingStorageWithdrawal(int itemId)
    {
        final StorageWithdrawalInteraction withdrawal = pendingStorageWithdrawalInteraction;
        if (withdrawal == null || withdrawal.getExpiresAtMillis() < System.currentTimeMillis())
        {
            pendingStorageWithdrawalInteraction = null;
            return false;
        }

        try
        {
            final ItemComposition item = itemManager.getItemComposition(canonicalItemId(itemId));
            final String itemName = normalizeName(item != null ? item.getName() : "");
            if (!withdrawal.getItemName().equals(itemName))
            {
                return false;
            }
            pendingStorageWithdrawalInteraction = null;
            debugLog("Skipping untradable storage withdrawal for {}", item != null ? item.getName() : itemId);
            return true;
        }
        catch (RuntimeException ex)
        {
            debugLog("Could not match storage withdrawal for item {}: {}", itemId, ex.getMessage());
            return false;
        }
    }

    private boolean isRecoveryActive()
    {
        if (recoveryInterfaceOpen)
        {
            return true;
        }

        final RecoveryInteraction recovery = pendingRecoveryInteraction;
        if (recovery == null)
        {
            return false;
        }
        if (recovery.getExpiresAtMillis() >= System.currentTimeMillis())
        {
            return true;
        }

        pendingRecoveryInteraction = null;
        return false;
    }

    private boolean isDirectRecoveryInteraction(String menuOption, String menuTarget)
    {
        if (!RECOVERY_TARGET_NAMES.contains(menuTarget))
        {
            return false;
        }

        if ("death".equals(menuTarget))
        {
            return "talk-to".equals(menuOption);
        }

        return "open".equals(menuOption)
            || "collect".equals(menuOption)
            || "retrieve".equals(menuOption)
            || "claim".equals(menuOption);
    }

    private boolean isRecoveryCollectionOption(String menuOption)
    {
        return menuOption.startsWith("take")
            || "collect".equals(menuOption)
            || "retrieve".equals(menuOption)
            || "claim".equals(menuOption);
    }

    private String recoverySourceName()
    {
        final RecoveryInteraction recovery = pendingRecoveryInteraction;
        return recovery != null ? recovery.getSourceName() : "recovery interface";
    }

    private void captureInventorySnapshot()
    {
        inventorySnapshot.clear();
        inventorySnapshot.putAll(aggregateContainerItems(client.getItemContainer(net.runelite.api.InventoryID.INVENTORY.getId())));
        inventorySnapshotInitialized = true;
    }

    private static Map<Integer, Integer> aggregateContainerItems(ItemContainer itemContainer)
    {
        final Map<Integer, Integer> items = new LinkedHashMap<>();
        if (itemContainer == null || itemContainer.getItems() == null)
        {
            return items;
        }

        for (Item item : itemContainer.getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }

            items.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        return items;
    }

