    private static String compactMetricDecimal(double value)
    {
        if (Math.abs(value - Math.rint(value)) < 0.000001D)
        {
            return DECIMAL_FORMATS.INTEGER.format(value);
        }
        return DECIMAL_FORMATS.ONE_DECIMAL.format(value);
    }

