        }
        catch (RuntimeException ignored)
        {
            try
            {
                return LocalDateTime.parse(cleaned, SERVER_UTC_FORMAT).toInstant(ZoneOffset.UTC);
            }
            catch (RuntimeException ex)
            {
                return null;
            }
        }
