    private static final class CompactEventTimePanel extends JPanel
    {
        private static final int VISIBLE_DAYS = 7;
        private final Instant startsAt;
        private final Instant endsAt;
        private final Color color;
        private final boolean ongoing;
        private final boolean dayFirstDates;
        private final boolean twentyFourHourTime;
        private final ZonedDateTime visibleStart;
        private final ZonedDateTime visibleEnd;

        CompactEventTimePanel(Instant startsAt, Instant endsAt, Color color, boolean ongoing, boolean dayFirstDates, boolean twentyFourHourTime)
        {
            this.startsAt = startsAt;
            this.endsAt = endsAt;
            this.color = color == null ? HIGHLIGHT : color;
            this.ongoing = ongoing;
            this.dayFirstDates = dayFirstDates;
            this.twentyFourHourTime = twentyFourHourTime;
            this.visibleStart = ZonedDateTime.now(LOCAL_ZONE).truncatedTo(ChronoUnit.MINUTES);
            this.visibleEnd = visibleStart.plusDays(VISIBLE_DAYS);
            setPreferredSize(new Dimension(185, 70));
            setMinimumSize(new Dimension(150, 70));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, 70));
            setOpaque(false);
        }

        @Override
        protected void paintComponent(Graphics graphics)
        {
            super.paintComponent(graphics);
            final Graphics2D g = (Graphics2D) graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            final int width = getWidth();
            final int left = 0;
            final int right = Math.max(left + 1, width - 1);
            final int barY = 56;

            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
            g.setColor(MUTED);
            g.drawString("Start " + ParentsGuildDateTimeFormatter.formatDateTime(startsAt, dayFirstDates, twentyFourHourTime), left, 14);
            g.drawString("End " + ParentsGuildDateTimeFormatter.formatDateTime(endsAt, dayFirstDates, twentyFourHourTime), left, 29);

            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
            for (int day = 0; day <= VISIBLE_DAYS; day++)
            {
                final int x = left + Math.round((right - left) * (day / (float) VISIBLE_DAYS));
                g.setColor(new Color(65, 65, 65));
                g.drawLine(x, 41, x, 64);
                if (day < VISIBLE_DAYS && day % 2 == 0)
                {
                    g.setColor(MUTED);
                    final int labelX = Math.min(Math.max(left, x - 6), Math.max(left, right - 22));
                    g.drawString(ParentsGuildDateTimeFormatter.calendarDayFormatter(dayFirstDates).format(visibleStart.plusDays(day)), labelX, 47);
                }
            }

            g.setStroke(new BasicStroke(5F, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(new Color(58, 58, 58));
            g.drawLine(left, barY, right, barY);
            g.setColor(color);
            final Instant now = Instant.now();
            final Instant displayStart = ongoing && now.isAfter(startsAt) ? now : startsAt;
            final int x1 = xForInstant(displayStart, left, right);
            final int x2 = Math.max(x1 + 4, xForInstant(endsAt, left, right));
            if (x2 >= left && x1 <= right)
            {
                g.drawLine(Math.max(left, x1), barY, Math.min(right, x2), barY);
            }
            if (ongoing)
            {
                final int nowX = xForInstant(now, left, right);
                g.setStroke(new BasicStroke(1F));
                g.setColor(new Color(236, 222, 174));
                g.drawLine(nowX, 50, nowX, 64);
                g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
                g.drawString("Now", Math.min(Math.max(left, nowX - 9), Math.max(left, right - 18)), 53);
            }
            g.dispose();
        }

        private int xForInstant(Instant instant, int left, int right)
        {
            final long rangeMillis = Math.max(1L, ChronoUnit.MILLIS.between(visibleStart, visibleEnd));
            final long offsetMillis = Math.max(0L, Math.min(rangeMillis, ChronoUnit.MILLIS.between(visibleStart, ZonedDateTime.ofInstant(instant, LOCAL_ZONE))));
            return left + Math.round((right - left) * (offsetMillis / (float) rangeMillis));
        }
    }

    private static final class FullWidthPanel extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return Math.max(16, visibleRect.height - 16);
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

package com.parentsguild.parentsguild;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.FormatStyle;
import java.util.Locale;

final class ParentsGuildDateTimeFormatter
{
    private ParentsGuildDateTimeFormatter()
    {
    }

    static String formatDateTime(Instant instant, boolean dayFirstDates, boolean twentyFourHourTime)
    {
        return dateTimeFormatter(dayFirstDates, twentyFourHourTime).format(instant);
    }

    static DateTimeFormatter dateTimeFormatter(boolean dayFirstDates, boolean twentyFourHourTime)
    {
        final Locale locale = Locale.getDefault();
        final DateTimeFormatter date = dayFirstDates
            ? DateTimeFormatter.ofPattern("dd/MM/yy", locale)
            : DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT).withLocale(locale);
        final DateTimeFormatter time = twentyFourHourTime
            ? DateTimeFormatter.ofPattern("HH:mm", locale)
            : DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT).withLocale(locale);
        return new DateTimeFormatterBuilder()
            .append(date)
            .appendLiteral(' ')
            .append(time)
            .toFormatter(locale)
            .withZone(ZoneId.systemDefault());
    }

    static DateTimeFormatter calendarDayFormatter(boolean dayFirstDates)
    {
        final Locale locale = Locale.getDefault();
        if (dayFirstDates)
        {
            return DateTimeFormatter.ofPattern("dd/MM", locale).withZone(ZoneId.systemDefault());
        }

        final String sample = DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT)
            .withLocale(locale)
            .format(LocalDate.of(2026, 11, 22));
        final int monthIndex = sample.indexOf("11");
        final int dayIndex = sample.indexOf("22");
        final String pattern = dayIndex >= 0 && monthIndex >= 0 && dayIndex < monthIndex ? "d/M" : "M/d";
        return DateTimeFormatter.ofPattern(pattern, locale).withZone(ZoneId.systemDefault());
    }
}

package com.parentsguild.parentsguild;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class ParentsGuildBingoOverlay extends Overlay
{
    private static final Color BINGO_NAME_COLOR = new Color(86, 214, 108);
    private static final Color TEAM_NAME_COLOR = new Color(232, 74, 74);
    private static final Color DETAILS_COLOR = Color.WHITE;
    private static final Color SHADOW_COLOR = new Color(0, 0, 0, 180);
    private final ParentsGuildPlugin plugin;

    @Inject
    ParentsGuildBingoOverlay(ParentsGuildPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final ParentsGuildPlugin.BingoOverlayState state = plugin.getBingoOverlayState();
        if (state == null || !state.isVisible())
        {
            return null;
        }

        final Font originalFont = graphics.getFont();
        final Font overlayFont = originalFont.deriveFont(Font.BOLD, 16F);
        graphics.setFont(overlayFont);
        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        final String bingoNameText = state.getBingoName() + ":";
        final String teamNameText = " " + state.getTeamName();
        final String timeText = ":" + ParentsGuildDateTimeFormatter.formatDateTime(
            Instant.now(),
            plugin.useDayFirstDates(),
            plugin.useTwentyFourHourTime()
        );
        final FontMetrics metrics = graphics.getFontMetrics();
        final int padding = 2;
        final int x = padding;
        final int y = padding + metrics.getAscent();
        final int nameWidth = metrics.stringWidth(bingoNameText);
        final int teamWidth = metrics.stringWidth(teamNameText);

        drawShadowedText(graphics, bingoNameText, x, y, BINGO_NAME_COLOR);
        drawShadowedText(graphics, teamNameText, x + nameWidth, y, TEAM_NAME_COLOR);
        drawShadowedText(graphics, timeText, x + nameWidth + teamWidth, y, DETAILS_COLOR);

        final int totalWidth = nameWidth + teamWidth + metrics.stringWidth(timeText) + (padding * 2);
        final int height = metrics.getHeight() + (padding * 2);
        graphics.setFont(originalFont);
        return new Dimension(totalWidth, height);
    }

    private static void drawShadowedText(Graphics2D graphics, String text, int x, int y, Color color)
    {
        graphics.setColor(SHADOW_COLOR);
        graphics.drawString(text, x + 1, y + 1);
        graphics.setColor(color);
        graphics.drawString(text, x, y);
    }
}

